const days=[['Discovery','A stakeholder asks for a new dashboard. What would you want to learn before adding it to the roadmap?'],['Problem framing','A team is debating features, but customers describe a recurring delay. How would you frame and validate the underlying problem?'],['Backlog clarity','A top-ranked item says “make reports better.” What questions would help turn it into a useful, testable slice?'],['Prioritization','Two teams need the same engineer this sprint. What evidence and trade-offs would you bring into the decision?'],['Acceptance criteria','A user story works for the happy path but says nothing about permission or failure cases. What would you clarify?'],['Outcome metrics','A release shipped on time, but adoption is flat. What outcome signal and follow-up would you propose?'],['Stakeholder alignment','Sales wants a promised date; engineering has unresolved integration risk. How would you communicate a responsible next step?'],['Risk review','A dependency is controlled by another organization. How can the team make uncertainty visible and reduce it?'],['Sprint review','A demo went well, but no users attended. What would you change before the next review?'],['Continuous improvement','The team carries unfinished work into three consecutive sprints. What would you inspect before proposing a process change?'],['Technical trade-off','A small shortcut speeds a release but adds ongoing maintenance. How would you help the team make that cost visible?'],['Ethical product choice','A requested metric may expose sensitive user details. What would you ask before agreeing to collect it?']];const KEY='po-ai-daily-v1';let st;try{st=JSON.parse(localStorage.getItem(KEY)||'{}')}catch{st={}}st.done||=[];st.responses||={};st.day||=0;st.streak||=0;const $=q=>document.querySelector(q),save=()=>localStorage.setItem(KEY,JSON.stringify(st)),esc=x=>String(x||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function render(){const d=days[st.day%days.length];$('#track').textContent=`${d[0].toUpperCase()} · DAILY PRACTICE`;$('#title').textContent=d[0];$('#scenario').textContent=d[1];$('#response').value=st.responses[st.day]||'';$('#streak').textContent=st.streak;$('#completed').textContent=st.done.length;$('#path').innerHTML=days.map((x,i)=>`<div class="step${st.done.includes(i)?' done':''}"><span>${st.done.includes(i)?'✓':'○'} Day ${String(i+1).padStart(2,'0')} · ${x[0]}</span><button data-open="${i}">${i===st.day?'Today':'Open'}</button></div>`).join('');document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{st.day=+b.dataset.open;save();render()});$('#entries').innerHTML=st.done.length?st.done.map(i=>`<article class="card"><b>${days[i][0]}</b><p>${esc(st.responses[i])||'<i>No reflection written.</i>'}</p></article>`).join(''):'No completed practices yet.'}$('#save').onclick=()=>{st.responses[st.day]=$('#response').value;save();$('#review').textContent='Reflection saved in this browser.'};$('#check').onclick=()=>{st.responses[st.day]=$('#response').value;save();const text=$('#response').value.toLowerCase();const prompts=['Did I identify whose problem this is?','Did I seek evidence rather than assume?','Did I name an outcome or a way to learn?','Did I explain a trade-off or next step?'];const keys=[['user','customer','stakeholder'],['evidence','data','interview','learn'],['measure','metric','outcome','success'],['risk','trade-off','next','because']];$('#review').innerHTML=`<h3>Self-review</h3>${prompts.map((q,i)=>`<label><input type="checkbox">${q}</label>`).join('')}<p class="muted">These prompts help structure reflection; they do not grade professional skill.</p>`};$('#next').onclick=()=>{st.responses[st.day]=$('#response').value;if(!st.done.includes(st.day)){st.done.push(st.day);st.streak++}st.day=(st.day+1)%days.length;save();render();$('#review').textContent=''};$('#story').onclick=()=>{$('#storyOut').textContent=`As a ${$('#persona').value||'[user or role]'}, I want to ${$('#goal').value||'[action]'}, so that ${$('#value').value||'[value]'}.

Questions to resolve:
• Who has this need, and what evidence do we have?
• What should happen when the expected path fails?
• What would show that the outcome improved?`};$('#priority').onclick=()=>{const i=+$('#impact').value,e=+$('#effort').value,r=+$('#risk').value;$('#priorityOut').textContent=`Discussion prompt: customer impact ${i}/5, effort ${e}/5, uncertainty ${r}/5. What evidence supports each rating? Who benefits, what is the smallest useful experiment, and what should wait?`};$('#criteria').onclick=()=>{$('#criteriaOut').innerHTML=['Given the relevant starting condition…','When the user takes the action…','Then the expected outcome is…','What happens with no access, missing data, or an error?'].map(x=>`<div class="criteria">☐ ${x}</div>`).join('')};$('#nav').onclick=e=>{const b=e.target.closest('[data-view]');if(!b)return;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===b.dataset.view));if(b.dataset.view==='journal')render()};$('#export').onclick=()=>{const a=document.createElement('a'),blob=new Blob([JSON.stringify(st,null,2)],{type:'application/json'});a.href=URL.createObjectURL(blob);a.download='po-ai-daily-journal.json';a.click();URL.revokeObjectURL(a.href)};$('#reset').onclick=()=>{if(confirm('Clear this browser’s PO AI Daily progress and reflections?')){localStorage.removeItem(KEY);location.reload()}};render();
